// frontend/src/App.js
import React, { useState, useEffect } from "react";
import { Routes, Route } from "react-router-dom";
import Sidebar from "./components/Sidebar";

// Pages (create these under src/pages/ if you haven't already)
import HomePage from "./pages/HomePage";
import FlightSearch from "./pages/FlightSearch";
import HotelSearch from "./pages/HotelSearch";
import NewsPage from "./pages/NewsPage";

import "./App.css";

/**
 * App router + top-level layout
 * - Sidebar is always visible
 * - Main area shows the selected page via react-router
 *
 * Session persistence:
 * - sessions state is kept in localStorage "ai_chat_sessions"
 * - saveSessions pushes latest session to localStorage and attempts server persist
 */
export default function App() {
  const [sessions, setSessions] = useState([]);

  useEffect(() => {
    try {
      const raw = localStorage.getItem("ai_chat_sessions");
      if (raw) setSessions(JSON.parse(raw));
    } catch (e) {
      setSessions([]);
    }
  }, []);

  const saveSessions = (newSessions) => {
    setSessions(newSessions);
    localStorage.setItem("ai_chat_sessions", JSON.stringify(newSessions));
    // also attempt to persist server-side (non-blocking)
    fetch("/api/sessions/save", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(newSessions[0]), // save latest session
    }).catch(() => {});
  };

  const onLoadSession = (s) => {
    // Sidebar will call this when a session is selected.
    // We simply preserve overall sessions here; HomePage reads sessions via props.
    // If you want the router to navigate to Home when session loads, you can add that behavior.
    // For now, nothing else is required here.
  };

  const onNewChat = () => {
    // Optional hook if Sidebar's "New Chat" should clear session list or navigate.
    // Keep it empty — HomePage has its own new-chat logic.
  };

  return (
    <div className="app">
      <Sidebar sessions={sessions} onLoadSession={onLoadSession} onNewChat={onNewChat} />
      <main className="stage">
        <Routes>
          <Route path="/" element={<HomePage sessions={sessions} saveSessions={saveSessions} />} />
          <Route path="/flights" element={<FlightSearch />} />
          <Route path="/hotels" element={<HotelSearch />} />
          <Route path="/news" element={<NewsPage />} />
        </Routes>
      </main>
    </div>
  );
}
